function formatEntry(num, data) {
  const lines = [`  ${num}: {`, `    correctAnswers: ${JSON.stringify(data.correctAnswers)},`, `    summaryNote:`, `      '${data.summaryNote.replace(/'/g, "\\'")}',`, `    questionVi:`, `      '${data.questionVi.replace(/'/g, "\\'")}',`, `    explanations: {`];
  for (const [k, v] of Object.entries(data.explanations)) {
    lines.push(`      ${k}: '${v.replace(/'/g, "\\'")}',`);
  }
  lines.push(`    },`, `  },`);
  return lines.join('\n');
}

